"""Static CSS/JS assets for the GStudio local workbench.

The shared interface layer lives in ui/ember_ui/static/ as real files (also
exported verbatim to the open-source edition) and is served at /assets/<name>.
Files are read once as inert text, so served bytes and version hashes match the
files exactly. Assets for full-workbench-only modules stay in this module.
"""
from ..deployment import runtime_root as _deployment_root
import hashlib
import sys
from pathlib import Path

UI_ROOT = Path(__file__).resolve().parents[1]

from ..ember_ui.marks import EMBER_MARK_PATH  # noqa: E402

STATIC_ROOT = UI_ROOT / "ember_ui" / "static"
STATIC_CONTENT_TYPES = {".css": "text/css; charset=utf-8", ".js": "text/javascript; charset=utf-8"}
STATIC_ASSETS = {
    path.name: path.read_bytes().decode("utf-8")
    for path in sorted(STATIC_ROOT.iterdir())
    if path.is_file() and path.suffix in STATIC_CONTENT_TYPES
}


def asset_version(name: str) -> str:
    """Short content hash used as the cache-busting query of a static asset."""
    return hashlib.sha256(STATIC_ASSETS[name].encode("utf-8")).hexdigest()[:12]


# 余烬 · Ember R06 flame "e": one geometry for identity and AI action keys.
# Keep BRAND_MARK_* exports stable for existing callers.
BRAND_MARK_PATH = EMBER_MARK_PATH
BRAND_MARK_SVG = (
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="none">'
    f'<path d="{BRAND_MARK_PATH}" stroke="#27231F" stroke-width="27" stroke-linecap="round" stroke-linejoin="round"/>'
    '</svg>'
)

EMBER_FAVICON_SVG = (
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256">'
    '<rect width="256" height="256" rx="56" fill="#7A242A"/>'
    '<g transform="translate(128 128) scale(0.74) translate(-128 -129)">'
    f'<path d="{EMBER_MARK_PATH}" fill="none" stroke="#F6F2E9" stroke-width="30" stroke-linecap="round" stroke-linejoin="round"/>'
    '</g></svg>'
)

CSS = STATIC_ASSETS["workbench.css"]
TASK_DETAIL_CSS = STATIC_ASSETS["task-detail.css"]
# Run immediately after the sidebar, before main content or deferred assets:
# restoring at the end of the document visibly expands and scrolls it first.
SIDEBAR_STATE_JS = STATIC_ASSETS["sidebar-state.js"]
EXECUTION_CONFIRM_JS = STATIC_ASSETS["execution-confirm.js"]
TASK_DETAIL_JS = STATIC_ASSETS["task-detail.js"]

# Full-workbench-only: project favorites in the sidebar and project entry copy.
# The shared sidebar state and small-screen toggle are in sidebar.js.
PROJECT_NAVIGATION_JS = r"""(()=>{
  document.addEventListener('click',async event=>{
    const button=event.target.closest('[data-project-entry-copy]');if(!button)return;
    const copied=await window.GStudioUI.copyPrompt(button.dataset.projectEntryCopy);
    window.GStudioUI.toast(copied?'入口已复制':'复制失败，请选择路径或网址手动复制',copied?'info':'error',3500);
  });
  const favoriteForm = document.getElementById('sidebarFavoriteForm');
  function submitFavorite(row){
    if(favoriteForm.querySelector('button').disabled)return;
    favoriteForm.elements.project.value = row.dataset.sidebarProject;
    favoriteForm.elements.favorite.value = row.dataset.favorite;
    favoriteForm.elements.return_to.value = location.pathname+location.search+location.hash;
    favoriteForm.requestSubmit();
  }
  const favoriteMenu = document.getElementById('sidebarProjectMenu');
  const favoriteMenuButton = favoriteMenu?.querySelector('button');
  let favoriteMenuRow = null;
  let favoriteMenuScrollTop = 0;
  function closeFavoriteMenu(restore=false){
    if(!favoriteMenu || favoriteMenu.hidden) return;
    favoriteMenu.hidden = true;
    if(restore) favoriteMenuRow?.querySelector('a')?.focus();
  }
  function openFavoriteMenu(row,x,y){
    favoriteMenuRow = row;
    favoriteMenuScrollTop = document.querySelector('.sidebar-nav-main')?.scrollTop || 0;
    const saved = row.dataset.favorite === '0';
    favoriteMenuButton.textContent = saved ? '取消收藏' : '收藏置顶';
    favoriteMenu.hidden = false;
    favoriteMenu.style.left = Math.max(8,Math.min(x,innerWidth-favoriteMenu.offsetWidth-8))+'px';
    favoriteMenu.style.top = Math.max(8,Math.min(y,innerHeight-favoriteMenu.offsetHeight-8))+'px';
    favoriteMenuButton.focus();
  }
  document.querySelectorAll('[data-sidebar-project]').forEach(row=>{
    row.querySelector('.sidebar-favorite-button').addEventListener('click',()=>submitFavorite(row));
    row.addEventListener('contextmenu',event=>{event.preventDefault();openFavoriteMenu(row,event.clientX,event.clientY)});
    row.querySelector('a').addEventListener('keydown',event=>{
      if(event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10')){
        event.preventDefault();const box=row.getBoundingClientRect();openFavoriteMenu(row,box.left,box.bottom);
      }
    });
  });
  favoriteMenuButton?.addEventListener('click',()=>{closeFavoriteMenu();if(favoriteMenuRow)submitFavorite(favoriteMenuRow)});
  document.addEventListener('click',event=>{if(!favoriteMenu?.contains(event.target))closeFavoriteMenu()});
  document.addEventListener('keydown',event=>{if(event.key==='Escape' || event.key==='Tab')closeFavoriteMenu(true)});
  window.addEventListener('resize',()=>closeFavoriteMenu());
  document.querySelector('.sidebar-nav-main')?.addEventListener('scroll',event=>{if(event.target.scrollTop!==favoriteMenuScrollTop)closeFavoriteMenu()},{passive:true});
})();"""

